    if(state.update&&!state.dismissed?.update)out.push(`<div class="app-banner">${icon('download')}<span><strong>Update ${escape(state.update.version)} is ready.</strong> Close Sacred Tweaks and open Sacred Tweaks Updater to install it.</span><button class="text-button" data-action="update-notes">What’s new</button><button class="text-button" data-action="dismiss-banner" data-k="update">Dismiss</button></div>`);
