    const current=state.boot?.version||'0',v=update.value,newer=(a,b)=>{const x=a.split('.').map(Number),y=b.split('.').map(Number);for(let i=0;i<4;i++){if((x[i]||0)!==(y[i]||0))return (x[i]||0)>(y[i]||0);}return false;};
    if(update.status==='fulfilled'&&v?.version&&newer(v.version,current))state.update=v;
