    $('#app').innerHTML=`<main class="welcome tier-welcome-${escape(t.toLowerCase())} effect-${effect}"><div class="particles"></div><div class="brand-mark large">S</div><div>${tier(t)}</div><h1>${escape(w.title || `Welcome, ${state.session.user.username}.`)}</h1><p>${escape(w.message || w.text || 'Your workspace is ready. Make every setting intentional.')}</p>${w.badge?`<span class="tag" style="margin-top:15px">${escape(w.badge)}</span>`:''}${button('Enter your workspace','enter-workspace','primary','','arrow')}<p class="hint" style="margin-top:20px">Macros start disabled. You are always in control.</p></main>`;
