    if (view==='measurements') return renderMeasurements();
    if (view==='backups') return renderBackups();
    if (view==='misc') return renderMisc();
    if (view==='theme') return renderTheme();
    if (view==='account') return renderAccount();
    if (view==='training') return renderTraining();
