    root.innerHTML='<div class="tour-spot"></div><div class="tour-card"><div class="tour-step"></div><h2></h2><p></p><div class="tour-dots"></div><div class="tour-actions"><button class="text-button" data-tour="skip">Skip tour</button><span class="grow"></span><button class="btn ghost small" data-tour="back">Back</button><button class="btn primary small" data-tour="next">Next</button></div></div>';
    document.body.appendChild(root);
    const spot=$('.tour-spot',root),card=$('.tour-card',root);
    const finish=()=>{root.classList.add('closing');setTimeout(()=>root.remove(),250);const uid=String(state.session?.user.id||'');state.meta=state.meta||{};state.meta.tours={...(state.meta.tours||{}),[uid]:true};pageData.meta=state.meta;saveWorkspace('meta');};
